-- The Palladium Fantasy invocations the catalog did not have.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local  apps/character-creator/db/add-pf-invocations.sql
--   node scripts/d1-apply.mjs --remote apps/character-creator/db/add-pf-invocations.sql
--
-- 27 spells: level 1: 2, level 2: 1, level 3: 2, level 5: 2, level 6: 5, level 7: 5, level 8: 3, level 9: 3, level 10: 2, level 11: 1, level legend: 1.
--
-- READ FROM THE PDF'S OWN TEXT LAYER, geometrically, with
-- scripts/read-columns.py - no OCR and no model call. The book carries a real
-- text layer, so the failure mode that cost the Rifts imports their review time
-- does not arise here.
--
-- THE LEVEL COMES FROM THE INDEX. The book prints a spell's level only in the
-- section heading of its alphabetical list BY LEVEL (printed 187); a
-- description page states no level at all, with six exceptions noted below.
--
-- TWO INDEPENDENT READINGS OF EVERY COST, which is the check that matters:
-- the figure the index prints beside the name, and the P.P.E. line in the
-- spell's own stat block - usually spelled out in words there, "Twenty-Five"
-- against the index's 25. 27 of 27 agree.
--
-- The two index tables also check each other. Parsed side by side they
-- disagree on exactly two costs out of 182 - See the Invisible (4 or 6) and
-- Curse: Phobia (40 or 50) - and neither is in this batch.
--
-- WHICH SPELLS THESE ARE was decided by scripts/catalog-diff.mjs against the
-- whole spells table, not by a hand-rolled matcher. It reported 29 missing;
-- two of those were FALSE GAPS found by hand, and both are naming, not
-- content:
--   * "Swim as a Fish" is the catalog's "Swim as a Fish (lesser)", same level
--     and same cost.
--   * "Invulnerability: Limited" is the catalog's "Invulnerability", same
--     level and same cost; the description page heads it "Invulnerability
--     (limited)" and the index adds the colon.
-- Three more looked like near matches and are genuinely different spells:
-- Animate Object against the Warlock's "Earth: Animate Object", Circle of
-- Concealment against "Concealment", and Time Capsule (Touch, 30, preserves
-- objects) against the Rifts "Ley Line Time Capsule" (15).
--
-- NOTHING TO RECORD FROM THE DISAGREEMENTS. catalog-diff reported 21 rows
-- where a stored value differs from the book. Fourteen already carry the
-- Palladium figure in variant_note from add-palladium-variants.sql; four are
-- costs the book qualifies and the catalog already explains in ppe_note
-- (Amulet, Close Rift, Create Golem, Create Magic Scroll); and four are the
-- Spells of Legend, which the catalog stores at level 15 with a note saying so.
-- The later book still wins and no stored number changes here.
--
-- ONE PAGE ARGUES WITH THE INDEX. Exactly six description blocks state a level
-- of their own, and five are the book's own Spells of Legend. The sixth is The
-- Finger of Lictalon, which the index files under Level Eleven. The index
-- wins - see its variant_note for why - and the losing reading is recorded
-- rather than discarded.
--
-- SYSTEM IS 'palladium-fantasy', not NULL. These are the spells no Rifts book
-- imported so far prints, and inSystem() reads a tag as a restriction: "A
-- Palladium Fantasy spell chapter must not offer its spells to a Rifts mage."
-- If a later Rifts import prints one, that is the moment to move it to 'both',
-- the same trigger the cross-system gear fix uses.
--
-- INSERT OR IGNORE on a UNIQUE name: re-running this adds nothing and cannot
-- overwrite a row that already exists.

INSERT OR IGNORE INTO spells
  (name, level, ppe, ppe_note, range, duration, damage, saving_throw,
   area_of_effect, casting_time, description, variant_note, system,
   source_book, source)
VALUES
  ('Increase Weight', 1, 4, NULL, 'Self or on others up to 100 feet (30.5 m) away.', 'Two minutes (8 melee rounds) per level of experience.', NULL, 'Standard. Those who roll a successful saving throw vs magic are not affected. However, objects have no saving throw and are affected automatically.', NULL, NULL, 'The spell caster is able to increase the weight of any one specific living creature or object one hundred pounds (45 kg) per level of his experience. This can be used to make a person or object too heavy or difficult to move, to slow down a pursuer, and similar mischief. A character who is made to weigh twice (or more) his normal weight will see his speed attribute temporarily reduced by half. Note that the appearance of the person or item does not change, only his/its mass.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Ventriloquism', 1, 3, NULL, '10 foot (3 m) radius.', 'Instant', NULL, 'Standard', NULL, NULL, 'This invocation enables the spell caster to perfectly use ventriloquism on any inanimate object, tree, vegetation or animal. Basically the same as the skill at a 90% proficiency.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Weightlessness', 2, 6, NULL, '60 feet (18.3m).', '30 seconds (two melees) per level of experience.', NULL, 'Standard', NULL, NULL, 'Weightlessness is the exact opposite of the first level, increase weight spell. The spell caster is able to reduce the weight of any one object, person or creature by 100 pounds (45 kg) per each level of experience, down to a maximum of half an ounce. Characters or items that are virtually weightless can be carried with ease, used to trick people, float on the wind or to slow down opponents. Characters whose weight is reduced to nearly nothing will see their speed reduced by 75% and may be forced to hold on to rope or objects to prevent themselves from being carried away on the wind! A wind of one mile per hour (1.6 km) or faster will blow the character around like a feather or leaf caught in the wind! Likewise, the damage inflicted from striking attacks (punches, kicks, sword strikes, etc.) and the amount of weight the person can lift and carry are also reduced by 75%, because the weightless character doesn''t have the mass to inflict serious damage or carry heavy items.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Faerie Speak', 3, 5, NULL, 'Self or others.', 'Five minutes per level of the spell caster', NULL, 'None', NULL, NULL, 'This spell enables the spell caster (or two others by touch) to understand and speak the language of the faerie folk.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Sense Traps', 3, 7, NULL, 'Self', 'One minute (4 melee rounds) per level of experience.', NULL, 'None', NULL, NULL, 'This spell endows the spell caster with a sort of sixth sense which enables him to sense traps. This is done by simply looking over an object or area no further than six feet (1.8 m) away. Unfortunately, while the spell detects and locates the traps, it does not identify the specific danger or deactivate them. Nor does this spell locate secret compartments, doors or passageways.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Mend Cloth', 5, 12, NULL, 'Touch or within three feet (0.9 m); line of vision.', 'Instant and permanent.', NULL, 'Not applicable.', NULL, NULL, 'A spell of transformation that can make a tattered, torn, holey or old piece of fabric or an article of clothing the size of a blanket (shirt, pants, cape, pair of sock or gloves, and similar) as good as new - magically repairing tears, holes, thread bare areas from wear, etc. This spell can also be used to get rid of otherwise impossible to remove stains. The magic only works on cotton, wool, and silk cloth; not leather, felt, furs, rope, metal, padded armor or articles "filled" with feathers or other types of padding.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Size of the Behemoth', 5, 12, NULL, 'Self or other.', 'Two minutes (8 melee rounds) per level of experience.', NULL, 'None for self, standard for others.', NULL, NULL, 'This spell can be cast upon oneself or another person within the spell caster''s line of vision and no further than 30 feet 12.2 m) away. The incantation increases the size of the person to 20 feet (6 m) tall, weight to 1200 pounds (540 kg), and P.S. to 30, but speed is reduced to 6. The spell affects only the physical body and not the clothes, armor, weapons, or possessions the person was wearing or holding.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Animate Object', 6, 15, NULL, '60 feet (18.3 m); line of vision.', 'Two melee rounds per level of experience.', NULL, 'None', NULL, NULL, 'This incantation allows the spell caster to animate and control any object or objects under a total of 50 pounds (22.6 kg). The spell caster is able to mentally direct the object(s) to do just about anything: a table to walk, a broom to sweep, etc. The spell caster can cause the object to hover up to six feet (1.8 m) off the ground and move in any direction. If the object(s) is used to attack, the total number of attacks possible per melee is equal to the spell caster''s. So if four brooms are animated and the mage has four attacks per melee round, one broom can strike four times or all four can strike once each, or any combination there of. Roll to strike for each attacking object. Any dodge or parry by the object counts as a melee attack/action. No combat bonuses apply other than +1 on initiative. The animation of objects requires the spell caster''s full attention and concentration, so no other spells can be cast or action taken as long as the character is using this magic. Consequently, if he is knocked out or killed, the spell is instantly cancelled. Likewise, if his vision is impaired/obscured he temporarily loses control of that object(s), but can regain control if he can maneuver himself to see it again.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Control the Beasts', 6, 18, NULL, '100 feet (30.5 m)', 'Two minutes (8 melee rounds) per level of experience.', NULL, 'Standard', NULL, NULL, 'The spell caster is able to control two animals (mammals, birds, amphibians, reptiles, and fish, but not insects or creatures of magic) per level of experience, within his line of vision, up to 60 feet (18.3 m) away. The animal(s) responds as if it is tamed, trained and loyal to the spell caster. All creatures affected will obey simple commands like stay, sit, go, come, attack, kill, etc. This spell does not affect any intelligent creatures, humanoids, werebeasts or creatures of magic. Animals that successfully save vs magic may follow the lead of animals that don''t save. This is especially true of pack animals. Or the beast may be confused upon seeing other animals respond in a positive way to the mage, and simply leave the area.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Create Bread & Milk', 6, 15, NULL, 'Up to 30 feet (9 m) away.', 'Permanent', NULL, 'None', NULL, NULL, 'This incantation creates 2D6 loaves of bread and one gallon of milk held in jugs which disappear when emptied.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Detect Poison', 6, 10, NULL, '15 feet', 'Instant', NULL, 'None', NULL, NULL, 'The spell caster is able to direct his sight and concentration on a particular object, powder, liquid, plant, drink or food, and detect whether or not it is poisonous or laced with poison. Poison includes harmful or mind, mood, and physically altering drugs.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Fire Fist', 6, 15, NULL, 'Self', 'One minute (four melee rounds) per level of experience.', NULL, 'Dodge or parry only.', NULL, NULL, 'The spell caster''s fist seems to be enveloped in a ball of flame that does not burn his flesh, but inflicts 3D6 damage from punches plus any P.S. damage bonus! This is considered a magic attack/weapon and can hurt supernatural beings as well as be used to parry other magic weapons. The fire fist strike can only be parried by magic weapons without inflicting damage.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Circle of Concealment', 7, 15, '15 to conceal for one hour per level; 100 as a ritual, for one year per level', '20 foot (6.1 m) radius per level of experience. As a ritual, use the sorcerer with the highest level, and add 10 feet (3.0 m) per additional magician involved in the ritual.', 'One hour per level of experience/one year per level of experience.', NULL, 'See below.', NULL, NULL, 'This spell hides an area from most people. Anybody passing by the area will pay no attention to anything concealed by the circle. The circle can also be "programmed" so that certain individuals, group members, or those who know the right passwords can see past the mystical effect. A save versus ritual magic will allow somebody else to sense that something is "wrong" about the area, and may lead to the discovery of whatever is hidden by the circle. Magic and psionic powers like detect P.P.E., detect magic, and negate magic may pierce the circle of concealment and reveal what''s hidden within, but the circle gets to save vs magic or psionics with the bonuses of its creator. The circle can be a temporary hiding place for a few hours, or longlasting, with a duration measured in years. The first usage only costs 15 P.P.E., while the second requires 100 P.P.E. points plus the mage permanently loses one P.E. attribute point.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Immobilize', 7, 25, NULL, '60 feet (18.3m)', '2 melee rounds (30 seconds) per level of experience.', NULL, 'Special; if a successful save is made, the player rolls 1D4 to determine how many melee rounds his character is immobilized. After that time his character is able to move freely out of the cone, but cannot move to affect anything inside it.', NULL, NULL, 'This spell creates a transparent glittering cone, 20 feet (6 m) in diameter and 40 feet (12.2 m) tall (the spell caster may make it smaller if desired). The cone halts EVERYTHING within its scope. Missile weapons, speech, movement, flight, everything is momentarily frozen in time. Anyone entering or touching the glittering cone of light is also instantly immobilized. When the spell time elapses, any missile weapons or creatures in flight will drop to the ground while speech and movement will continue.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Wink-Out', 7, 20, '20 for one minute, then 10 more per additional minute; five minute maximum, costing 60', 'Self', 'Varies', NULL, 'Unwilling travelers can try to save; standard.', NULL, NULL, 'minutes he is "winked out" at an additional cost of 10 P.P.E. per each minute; five minute maximum (costing 60 P.P.E.). The character seems to disappear or teleport to a different location - it is impossible for an observer to tell which might be the case. In reality, the spell caster has really created, and stepped into, a very temporary time hole in another dimension. Time inside the wink-out time hole passes at the rate of 15 seconds per minute; i.e. one minute in the normal world will seem like one melee round (15 seconds) to the character(s) in the time hole, while five minutes will seem like 75 seconds to the time traveler who winked-out. During the wink-out phase, the character cannot be located by normal vision or scent, psionic or mystical means; it is as if the spell caster has vanished off the face of the planet (and he has). While winked out, the character can use his time (15 seconds per each minute) to reload weapons, draw new weapons, cast spells on himself (or his companions), prepare to cast a spell the moment he reappears, hide any small objects on his person, destroy an item, drink a potion, and similar tasks. Note, nothing can be left behind in the temporary time pocket.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Witch Bottle', 7, 28, NULL, 'Person wearing it.', 'One year per level of the spell caster.', NULL, 'None', NULL, NULL, 'A witch bottle is a magic charm that will protect the wearer from attacks or harm from a witch. This is a rare spell magic formula that requires very specific components and is created for a particular individual. A witch bottle can be used only by the person it was created for. Anyone else using it is not protected in any way. The witch bottle is a spell that must be cast in secret and seclusion. Alchemists and mages typically sell a witch bottle to anyone who can afford it; price range is typically 4,000-10,000 gold. The ingredients: A sturdy pint bottle, a cork to cap the bottle, lead to seal it, a half pint of ram''s blood, three small iron nails, seven thorns, a pinch of salt, and some hair and nail clippings from the person who seeks protection. All these ingredients are placed into the bottle, boiled over a fire at midnight while the incantation is invoked, corked and sealed. The protection of a witch bottle: 1. +3 to save against spells, curses, circles, rituals, and other magic cast/created by a witch. This also includes magic attacks from the witch''s demon familiar. The bottle protects the person only from magic attacks from witches; other types of magic and O.C.C.s are not affected. 2. Impervious to charm, mind control and possession by witches or their familiars. 3. The witch bottle can also hold a witch (but not her familiar) at bay, like a vampire faced with a crucifix.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('X-Ray Vision', 7, 25, NULL, 'Self', 'Two melee rounds per level of the spell caster.', NULL, 'None', NULL, NULL, 'This spell empowers the mage with the ability to see through solid matter such as wood, stone, clay, dirt, and iron. However, it takes a few minutes of concentration to see through various substances. He cannot see through structures thicker than listed below, or through lead or containers magically "sealed." The following time is needed to see through these materials: One melee round: Two feet (0.6 m) of wood, cloth, or leather, one foot (0.3 m) of dirt, clay or stone, and a half foot (0.15 m) of metal. Two melee rounds: Four feet (1.2 m) of wood or cloth, two feet (0.6 m) of dirt, clay or stone, or one foot (0.3 m) of metal.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Love Charm', 8, 40, NULL, 'Touch', 'Five minutes (20 melee rounds) per level of experience.', NULL, 'Standard', NULL, NULL, 'This spell affects most intelligent beings, except gods, godlings, demon lords, entities, elementals and alien intelligences. The magic causes the character affected to fall madly and devotedly in love with the spell caster. Victims of this spell will believe, trust, and defend anything the spell caster says or does. They will also obey any request by their lover, including murder or suicide (the latter two requests provoke another saving throw). The charmed person will constantly stay at the caster''s side and will often suggest amorous pleasures. Side effects: This spell has two potential side effects: insane jealousy and permanence. Roll percentile dice: 01-50 No side effect. 51 -84 Insane jealousy for 1D4 days per level of the spell caster. 85-00 Permanent insane jealously and possessiveness. Insane jealousy and possessiveness: This person becomes unreasonably jealous and insanely possessive, and will try one of the following if he or she doesn''t receive affection from the object of his/her love (roll percentile dice or pick one): 01-10 Suicide 11-30 Will attack anybody the spell caster finds attractive or whom he/she would rather be with. 31-40 Stalks the spell caster, following and spy ings on him/her everywhere. May attack those who threaten his/her loved one or any love interest; tries to protect and defend loved one. 41-50 Will endure any hardship, insult and even physical harm as long as he or she can be near the object of affection. Follows the spell caster everywhere, but never deliberately tries to harm him or his friends. 51-65 Murder the spell caster/lover; can''t accept rejection. 66-85 Will try to win his/her lover''s affection by incessantly offering gifts, favors, and services, but squabbles with, and may belittle, trick, cheat, and cause trouble for anybody whom the spell caster loves or befriends (considered rivals for his/her affection). 86-00 Murder spell caster''s friends and/or loved ones. Permanence: If the spell becomes permanent, the charmed person will forever remain a love slave until the spell caster dies (roll on the previous insane jealousy table if the charmed person is rejected). If the mage runs away, the charmed person will seek him out until found. If the spell caster dies, the spell is broken, but there is a 10% chance the charmed person will be broken hearted and commit suicide. Note: This spell can be cast upon only one person at a time. If there are no side effects the charmed person will return to normal at the spell''s end. Characters of a good alignment try to avoid using this magic.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Sense Dimensional Anomaly', 8, 30, NULL, 'Self', 'Two minutes per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'This spell enables the wizard to feel ripples in the space-time continuum and often sense the general location of such anomalies. Senses the following: - The opening, closing and general location of dimensional Rifts and doorways within a 50 mile (80 km) area. - The opening and closing of mystic portals, dimensional teleportation, ley line storms, and time holes within one mile (1.6 km). - The opening, closing, and general location of dimensional envelopes within 100 feet (30m). - The opening, closing and general location of dimensional pockets within 10 feet (3 m; he can see into the pocket if he finds it). - Sense when a space warp (teleportation), wink-out, or time warp is occurring within a 100 foot (30 m) radius. - Sense the presence/essence of astral beings, two and fourth dimensional beings, entities and alien intelligences within a 100 foot (30 m) radius, but cannot pinpoint their location.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Time Capsule', 8, 30, NULL, 'Touch', 'Varies, up to 50 years per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'Everything placed in the time capsule is perfectly preserved. The equivalent of one minute passes for every year inside the capsule. To create a time capsule, the spell caster must place the items to be preserved into a container of some kind. The container can be a wooden crate, metal trunk, cardboard box, knapsack, bag, or just about anything as long as it can be completely closed. When the container is closed the spell can be cast. The magic creates an energy field that takes the container and everything inside it out of the normal time continuum. As long as the container remains unopened the magic remains in effect. The instant it is opened the time capsule spell ends. The time capsule can be hidden, buried, or just placed on a shelf. How easy it is to open the capsule depends entirely on the strength of the container. The seal spell can be used in conjunction with this magic.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Age', 9, 50, NULL, '90 feet (27.4 m).', 'Three melee rounds per level of experience.', NULL, 'Standard', NULL, NULL, 'This spell magically transforms its victim, humanoid or animal, to the limit of their natural age! Only supernatural beings and creatures of magic such as gods, demons, deevils, faerie folk, spirits, and dragons are not affected by this spell. The aged person will suffer the following: -4 on initiative -5 to strike -5 to dodge/parry -4 to damage Reduce P.S. P.P., P.E., P.B. and Speed.attributes by half! Reduce attacks per melee round and combat bonuses also by half.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Faeries'' Dance', 9, 55, NULL, '60 feet (18.3 m) distance, affects a 20 foot (6 m) radius.', '10 minutes per level of the spell caster.', NULL, 'Standard', NULL, NULL, 'This is the spell magic equivalent of the faeries'' magic that forces its victims to dance in a mad frenzy until they drop from exhaustion. When the spell is invoked, an eerie music permeates the air. All who hear the music within a 20 foot (6 m) radius will suddenly feel compelled to dance, unless they save vs magic! Victims dance against their will at a maddening pace around and around in a circle. They can be saved only by being forcibly pulled from the circle/circular radius of effect, or rendered unconscious (a globe of silence will not quiet the music or negate its effects). Note: Anyone entering the enchanted area must roll vs magic or be affected too. Dancing victims cannot perform skills, have no initiative, and are -8 to strike, parry, or dodge. At the end of the dance, or for every 20 minutes of dancing, the dancers must roll under their P.E. attribute number or fall to the ground dazed or unconscious for 2D6 melee rounds.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Monster Insect', 9, 50, '50 for dog-sized, 100 for bull or horse-sized', '3 feet (0.9 m); line of vision', 'Five minutes per level of the spell caster.', NULL, 'Not applicable.', NULL, NULL, 'The spell caster can magically transform an ordinary insect into a monster the size of dog or horse! The creature will obey simple commands from the mage who created it and is very aggressive; will fight to the death. A typical monster insect (ant, beetle, bee, etc.): Horror Factor: 13 A.R.: 16 if ant or beetle, 12 for all others. HitPoints/S.D.C.: 3D4x10 Attacks per melee round: Three Damage: 1D6 damage from claws, 3D6 damage from bite or stinger. Bonuses: +2 on initiative, +3 to strike and dodge, +1 to parry. Skills of Note: Climb 90/85, swim 80%, land navigation 80%, track humanoids and animals 80%, and can run or fly at a speed of 58 (40 mph/64 km; flying bugs run at half that speed).', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Dimensional Pocket', 10, 30, '30 for a temporary pocket, 140 for a long-term one', 'Self only', 'Varies. Temporary pockets last up to one hour per level of the spell caster. Long-term pockets can exist for years; six months per level of experience.', NULL, 'Not applicable.', NULL, NULL, 'This spell creates a portable dimensional pocket inside a sack (big enough to fit one''s hand in), purse, satchel, backpack, etc. The dimensional pocket spell requires a psychological orientation, so without a physical sack, bag, or pocket the power cannot work! The character will typically select one favorite pocket or bag as his focus of orientation. The character can reach into the dimensional "pocket," a limbo dimension, to retrieve items that he has placed there earlier. Items can be just about anything that could fit in a backpack, clothing, gold, food, diary, bottle of wine, weapons, etc. To anybody else, the container appears ordinary and empty (unless the character investigating can see dimensional anomalies, like the temporal wizard in Rifts World Book 3: England). Wizards seldom have more than one or two long-term dimensional pockets themselves and rarely sell "magic" bags with more than three years of life in them. The retail cost for such a bag can range from 90,000 to a half million gold, however the maker of the magic bag seldom gets more than 20%.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Phantom Horse', 10, 60, NULL, 'Immediate', 'One hour per level of experience.', NULL, 'None', NULL, NULL, 'The spell caster can magically conjure a horse composed entirely of magic energy. Those who don''t know better think it is a ghost, because it is semitransparent and glows with bluish white energy. Only the mage who conjured it and one additional person can ride it (even if the mage doesn''t have the horsemanship skill). The Phantom Horse has a P.B. of 26, a Spd of 88 (60 mph/96 km), actually runs four inches (0.12 m) above the ground and can leap 20 feet (6 m) high and 60 feet (18.3 m) lengthwise.', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Finger of Lictalon', 11, 150, NULL, 'Any sword, knife or spear held in the hand of the spell caster, or another by touch.', 'Special; 10 minutes per level of the spell caster or until the weapon is dropped (instantly turns back to normal).', NULL, 'None', NULL, NULL, 'This spell, credited to the legendary elf wizard, Lictalon, transforms an ordinary knife, sword or spear weapon into a superpowerful magic weapon. The weapon crackles with a blue-white flame that completely engulfs its length. The magic fire does not hurt the person holding it or any character of a good alignment, but inflicts 4D6 damage to mortal creatures and 1D6x10 to supernatural beings (demons, entities, gods, etc.) and creatures of magic (dragons, sphinx, faeries, etc.) of selfish or evil alignment.', 'The by-level index (printed 187) files this under Level Eleven and the Spells of Legend list does not name it, but its own page (printed 211) heads it "Level: Spell of Legend". The index wins: two independent readings put it at eleven, its 150 P.P.E. sits with the level elevens rather than the 1000-5000 of the legends, and it is not typeset in the Spells of Legend section.', 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import'),
  ('Metamorphosis: Dragon', 15, 2000, 'A Spell of Legend, beyond the fifteen levels', 'Self. Another can be transformed only if performed as a ritual.', '1D6 hours per level of the spell caster.', NULL, 'None', NULL, NULL, 'The spell caster can actually transform himself into a 30-50 foot (915.2 m) long dragon! The following attributes and abilities apply: - A.R. 14 - +1D4x120 S.D.C. - +1 attack per melee round. Elemental magic is the spell like powers of the warlock, elementals and some supernatural beings. Elemental spell only goes up to eighth level. Except for the handful of equivalent elemental spells found among the wizard''s incantations, most elemental magic is available exclusively to the Warlock O.C.C., elementals and some gods, demons, and supernatural beings. Like wizard spells, warlock magic has a base Elemental Magic An alphabetical listing by level & Element Level One: Air Breathe Without Air (3) Thunder Clap (2) Cloud of Slumber (4) Cloud of Steam (4) Create Light (2) Create Mild Wind (4) Stop Wind (5) Level Two: Air Change Wind Direction (6) Create Air (6) Heavy Breathing (5) Howling Wind (7) Levitate (7) Mesmerism (7) Miasma (7) Northwind (7) Silence (10) - +1 to spell strength, +2 to save vs horror factor, and +4 to save vs poison. - Inflicts +2D6 damage from punches, kicks, stomps, bite and tail swipes. - Fire Breath once per melee round: 3D6 damage, 12 foot (3.6 m) range. - Natural abilities (in addition to one''s own skills and magic abilities): Fly 40 mph (64 km), see the invisible, nightvision 100 feet (30.5 m), fire and cold resistant (half damage), impervious to disease, and bioregenerate 1D4x10 hit points or S.D.C. once every minute (4 melee rounds)!', NULL, 'palladium-fantasy', 'Palladium Fantasy RPG Main Book', 'import');


-- Read the result back rather than trusting the exit code.
SELECT count(*) AS pf_invocations FROM spells WHERE source_book = 'Palladium Fantasy RPG Main Book';
SELECT level, count(*) AS n FROM spells WHERE source_book = 'Palladium Fantasy RPG Main Book'
  GROUP BY level ORDER BY level;
SELECT count(*) AS with_a_description FROM spells
  WHERE source_book = 'Palladium Fantasy RPG Main Book' AND length(COALESCE(description, '')) > 40;
SELECT count(*) AS qualified_costs FROM spells
  WHERE source_book = 'Palladium Fantasy RPG Main Book' AND ppe_note IS NOT NULL;

